typedef struct { sqlite3 *db; BfActivation *activation; BfAuthority *authority; BfCommitment *commitment; BfCommerce *commerce; BfEvidence *evidence; BfForeignTwin *foreign; BfProof *proof; BfReservation *reservation; BfWorkgraph *work; BfTargetObligation *targets; } Owners;
typedef struct { int satisfied, supported; const char *reason; } Evaluation;
typedef struct { const BfInverseTransformationDescriptor *t; size_t target_index; } Candidate;

static const char *option(int argc,char **argv,const char *name){int i;for(i=2;i+1<argc;i++)if(!strcmp(argv[i],name))return argv[i+1];return NULL;}
static void usage(void){fputs("usage: bonfyre-semantic-optimizer synthesize --db FILE --target ID [--actor ID] [--at ISO] [--select POLICY]\n       bonfyre-semantic-optimizer reconcile --db FILE --target ID [--actor ID] [--at ISO]\n       bonfyre-semantic-optimizer admit --db FILE --target ID --predicate ID --transformation ID --actor ID [--at ISO]\n       bonfyre-semantic-optimizer inverse-lower --db FILE --handoff FILE [--actor ID] [--at ISO]\n       bonfyre-semantic-optimizer inverse-drain --db FILE --lowerer-dir DIRECTORY [--actor ID] [--at ISO] [--limit N]\n",stderr);}
static int schema(sqlite3 *db){return sqlite3_exec(db,
 "CREATE TABLE IF NOT EXISTS inverse_target_receipts(target_id TEXT PRIMARY KEY,state TEXT NOT NULL,checked_at TEXT NOT NULL,residual_count INTEGER NOT NULL,selection_policy TEXT NOT NULL);"
 "CREATE TABLE IF NOT EXISTS inverse_predicate_receipts(target_id TEXT NOT NULL,predicate_id TEXT NOT NULL,owner TEXT NOT NULL,state TEXT NOT NULL,reason TEXT NOT NULL,checked_at TEXT NOT NULL,PRIMARY KEY(target_id,predicate_id));"
 "CREATE TABLE IF NOT EXISTS inverse_closure_residuals(target_id TEXT NOT NULL,predicate_id TEXT NOT NULL,transformation_id TEXT NOT NULL,eclass INTEGER NOT NULL,pareto_state TEXT NOT NULL,checked_at TEXT NOT NULL,PRIMARY KEY(target_id,predicate_id,transformation_id));"
 "CREATE TABLE IF NOT EXISTS inverse_cross_owner_residuals(target_id TEXT NOT NULL,predicate_id TEXT NOT NULL,transformation_id TEXT NOT NULL,capability_binding TEXT NOT NULL,authority_requirement TEXT NOT NULL,protocol_contract TEXT NOT NULL,commitment_pattern TEXT NOT NULL,resource_pattern TEXT NOT NULL,effect_kind TEXT NOT NULL,compensation_pattern TEXT NOT NULL,state TEXT NOT NULL,checked_at TEXT NOT NULL,PRIMARY KEY(target_id,predicate_id,transformation_id));"
 "CREATE TABLE IF NOT EXISTS inverse_effect_admissions(target_id TEXT NOT NULL,predicate_id TEXT NOT NULL,transformation_id TEXT NOT NULL,state TEXT NOT NULL,reason TEXT NOT NULL,checked_at TEXT NOT NULL,PRIMARY KEY(target_id,predicate_id,transformation_id));"
 "CREATE TABLE IF NOT EXISTS inverse_target_reconciliations(target_id TEXT PRIMARY KEY,state TEXT NOT NULL,proof_invariant TEXT NOT NULL DEFAULT '',checked_at TEXT NOT NULL,detail TEXT NOT NULL);",NULL,NULL,NULL)==SQLITE_OK;}
static void now_iso(char out[32]){time_t n=time(NULL);struct tm t;gmtime_r(&n,&t);strftime(out,32,"%Y-%m-%dT%H:%M:%SZ",&t);}
static int open_owners(const char *path,Owners *o){memset(o,0,sizeof(*o));if(sqlite3_open(path,&o->db)!=SQLITE_OK||!schema(o->db))return 0;return bf_activation_open_database(o->db,&o->activation,stderr)==0&&bf_authority_open_database(o->db,&o->authority,stderr)==0&&bf_commitment_open_database(o->db,&o->commitment,stderr)==0&&bf_commerce_open_database(o->db,&o->commerce,stderr)==0&&bf_evidence_open_database(o->db,&o->evidence,stderr)==0&&bf_foreign_twin_open_database(o->db,&o->foreign,stderr)==0&&bf_proof_open_database(o->db,&o->proof,stderr)==0&&bf_reservation_open_database(o->db,&o->reservation,stderr)==0&&bf_workgraph_open(path,&o->work,stderr)==0&&bf_target_obligation_open(path,&o->targets,stderr)==0;}
static void close_owners(Owners *o){if(o->targets)bf_target_obligation_close(o->targets);if(o->work)bf_workgraph_close(o->work);if(o->reservation)bf_reservation_close(o->reservation);if(o->proof)bf_proof_close(o->proof);if(o->foreign)bf_foreign_twin_close(o->foreign);if(o->evidence)bf_evidence_close(o->evidence);if(o->commerce)bf_commerce_close(o->commerce);if(o->commitment)bf_commitment_close(o->commitment);if(o->authority)bf_authority_close(o->authority);if(o->activation)bf_activation_close(o->activation);if(o->db)sqlite3_close(o->db);}
static int bind(sqlite3 *db,const char *sql,int n,const char **v){sqlite3_stmt*s=NULL;int i,ok;if(sqlite3_prepare_v2(db,sql,-1,&s,NULL)!=SQLITE_OK)return 0;for(i=0;i<n;i++)sqlite3_bind_text(s,i+1,v[i],-1,SQLITE_TRANSIENT);ok=sqlite3_step(s)==SQLITE_DONE;sqlite3_finalize(s);return ok;}
/* WorkGraph names are projections, but they must remain stable and distinct
 * across arbitrary TargetObligation ids.  String length was a collision, not
 * an identity function. */
static unsigned inverse_name_hash(const char *text){unsigned h=2166136261u;const unsigned char *p=(const unsigned char *)text;while(*p){h^=*p++;h*=16777619u;}return h;}
static int evidence_ok(Owners *o,const BfTargetPredicateRecord*p){return !p->evidence_requirement[0]||bf_evidence_stands(o->evidence,p->evidence_requirement)==1;}
static Evaluation evaluate(Owners*o,const BfTargetPredicateRecord*p,const char*actor,const char*at){int found=0,r;BfCommitmentState cs;BfCommerceStage stage;Evaluation v={0,1,"owner_state_unsatisfied"};switch((BfInverseAdapter)p->adapter){
case BF_INVERSE_ADAPTER_COMMITMENT:if(p->owner_query>BF_COMMITMENT_COMPENSATED){v.supported=0;v.reason="invalid_generated_query";break;}r=bf_commitment_status(o->commitment,p->subject,&cs,&found);v.satisfied=r==0&&found&&cs==(BfCommitmentState)p->owner_query;v.reason=v.satisfied?"commitment_state_recorded":"commitment_state_missing";break;
case BF_INVERSE_ADAPTER_AUTHORITY:if(!actor||!*actor){v.reason="actor_required";break;}r=bf_authority_has(o->authority,actor,p->predicate,p->subject,at,NULL);v.satisfied=r==1&&p->owner_query==1;v.reason=v.satisfied?"authority_valid":"authority_missing_or_expired";break;
case BF_INVERSE_ADAPTER_RESERVATION:if(!p->valid_start[0]||!p->valid_end[0]){v.supported=0;v.reason="reservation_window_required";break;}if(p->authority_requirement[0]&&(!actor||bf_authority_has(o->authority,actor,p->authority_requirement,p->subject,at,NULL)!=1)){v.reason="reservation_authority_missing";break;}r=bf_reservation_covers(o->reservation,p->subject,p->valid_start,p->valid_end);v.satisfied=r==1&&p->native_state==BF_INVERSE_STATE_RESERVED;v.reason=v.satisfied?"temporal_capacity_held":"temporal_capacity_not_held";break;
case BF_INVERSE_ADAPTER_ACTIVATION:r=bf_activation_state(o->activation,p->subject,0,0);v.satisfied=r==BF_ACT_ACTIVATED&&p->native_state==BF_INVERSE_STATE_ACTIVATED;v.reason=v.satisfied?"resource_activated":"resource_not_activated";break;
case BF_INVERSE_ADAPTER_EVIDENCE:r=bf_evidence_stands(o->evidence,p->subject);v.satisfied=r==1&&p->owner_query==1;v.reason=v.satisfied?"evidence_stands":"evidence_missing";break;
case BF_INVERSE_ADAPTER_PROOF:r=bf_proof_invariant_is_proven(o->proof,p->subject);v.satisfied=r==1&&p->owner_query==1;v.reason=v.satisfied?"proof_frontier_proven":"proof_not_proven";break;
case BF_INVERSE_ADAPTER_FOREIGN:r=bf_foreign_twin_observed(o->foreign,p->subject,p->predicate);v.satisfied=r==1&&p->owner_query==1;v.reason=v.satisfied?"foreign_observed":"foreign_roundtrip_missing";break;
case BF_INVERSE_ADAPTER_COMMERCE:if(p->owner_query>=BF_COMMERCE_STAGE_COUNT){v.supported=0;v.reason="invalid_generated_query";break;}stage=(BfCommerceStage)p->owner_query;r=bf_commerce_reached(o->commerce,p->subject,stage,&found);v.satisfied=r==0&&found;v.reason=v.satisfied?"commerce_stage_recorded":"commerce_stage_missing";break;
case BF_INVERSE_ADAPTER_POLICY:v.supported=0;v.reason="policy_owner_binding_not_installed";break;
case BF_INVERSE_ADAPTER_WORK:{sqlite3_stmt*s=NULL;if(sqlite3_prepare_v2(o->db,"SELECT 1 FROM workgraph_nodes WHERE node_id=? AND status='completed'",-1,&s,NULL)!=SQLITE_OK){v.supported=0;v.reason="work_query_failed";break;}sqlite3_bind_text(s,1,p->subject,-1,SQLITE_TRANSIENT);r=sqlite3_step(s)==SQLITE_ROW;sqlite3_finalize(s);v.satisfied=r&&p->native_state==BF_INVERSE_STATE_COMPLETED;v.reason=v.satisfied?"work_done":"work_not_done";break;}
default:v.supported=0;v.reason="generated_adapter_invalid";}if(v.satisfied&&!evidence_ok(o,p)){v.satisfied=0;v.reason="evidence_requirement_not_met";}return v;}
static int pattern_matches(const BfInversePredicatePattern*p,const BfTargetPredicateRecord*r){return p->adapter==r->adapter&&p->native_state==r->native_state&&p->owner_query==r->owner_query;}
static int grammar_matches(const BfTargetPredicateRecord *r){size_t i;for(i=0;i<bf_inverse_owner_grammar_count;i++){const BfInverseOwnerGrammar*g=&bf_inverse_owner_grammar[i];if(!strcmp(g->owner,r->owner)&&!strcmp(g->predicate,r->predicate)&&!strcmp(g->expected,r->expected_state)&&g->adapter==r->adapter&&g->native_state==r->native_state&&g->owner_query==r->owner_query)return 1;}return 0;}
static int establishes(const BfInverseTransformationDescriptor*t,const BfTargetPredicateRecord*r){size_t i;for(i=0;i<t->establishes_count;i++)if(pattern_matches(&t->establishes[i],r))return 1;return 0;}
static int requirement_index(const BfInversePredicatePattern *pattern,const BfTargetPredicateRecord *records,size_t count){size_t i;for(i=0;i<count;i++)if(pattern_matches(pattern,&records[i]))return (int)i;return -1;}
static int requirements_declared(const BfInverseTransformationDescriptor*t,const BfTargetPredicateRecord *records,size_t count){size_t i;for(i=0;i<t->requires_count;i++)if(requirement_index(&t->requires[i],records,count)<0)return 0;return 1;}
static int64_t candidate_value(const BfInverseSemanticCost*c,BfInverseCostDimension d){const int64_t*v=&c->elapsed_minutes;return v[d];}
static int better_dimension(int64_t a,int64_t b,BfInverseCostDimension d){return (d==BF_COST_SUCCESS||d==BF_COST_EVIDENCE||d==BF_COST_ROUNDTRIP)?a>b:a<b;}
static int dominates(const BfInverseTransformationDescriptor*a,const BfInverseTransformationDescriptor*b){size_t d;int strict=0;for(d=0;d<=BF_COST_SEMANTIC_LOSS;d++){int64_t av=candidate_value(&a->cost,(BfInverseCostDimension)d),bv=candidate_value(&b->cost,(BfInverseCostDimension)d);if((d==BF_COST_SUCCESS||d==BF_COST_EVIDENCE||d==BF_COST_ROUNDTRIP)?av<bv:av>bv)return 0;if(av!=bv)strict=1;}return strict;}
static const BfInversePreferencePolicy *policy_named(const char*id){size_t i;for(i=0;i<bf_inverse_policy_count;i++)if(!strcmp(id,bf_inverse_policies[i].id))return&bf_inverse_policies[i];return NULL;}
static const BfInverseTransformationDescriptor *transformation_named(const char*id){size_t i;for(i=0;i<bf_inverse_transformation_count;i++)if(!strcmp(id,bf_inverse_transformations[i].id))return&bf_inverse_transformations[i];return NULL;}
static const BfInverseTransformationDescriptor *select_frontier(Candidate*c,size_t n,const BfInversePreferencePolicy*p){size_t i,j,best=(size_t)-1;int dead[128]={0};for(i=0;i<n;i++)for(j=0;j<n;j++)if(i!=j&&dominates(c[j].t,c[i].t))dead[i]=1;for(i=0;i<n;i++)if(!dead[i]){int decided=0;if(best==(size_t)-1){best=i;continue;}for(j=0;j<p->dimension_count;j++){int64_t a=candidate_value(&c[i].t->cost,p->dimensions[j]),b=candidate_value(&c[best].t->cost,p->dimensions[j]);if(a==b)continue;if(better_dimension(a,b,p->dimensions[j]))best=i;decided=1;break;}/* Same Pareto/policy vector: extract the canonical egglog e-class representative. */if(!decided&&c[i].t->eclass<c[best].t->eclass)best=i;}return best==(size_t)-1?NULL:c[best].t;}
static int emit_cross_owner(Owners*o,const char*target,const BfTargetPredicateRecord*p,const BfInverseTransformationDescriptor*t,const char*at){char capability[160],authority[300],commitment[512],compensation[256],mission[128],node[128];const char*vals[13];BfWorkgraphNodeSpec spec={0};BfWorkgraphResult r;snprintf(capability,sizeof(capability),"capability:%s",t->effect_kind);snprintf(authority,sizeof(authority),"%s",p->authority_requirement[0]?p->authority_requirement:"effect-time-recheck");snprintf(commitment,sizeof(commitment),"%s",t->creates_commitments);snprintf(compensation,sizeof(compensation),"%s",!strcmp(t->reversibility,"reversible")?"none":t->cost.compensation_cost_micros?"compensation-required":"compensation-contract-required");vals[0]=target;vals[1]=p->predicate_id;vals[2]=t->id;vals[3]=capability;vals[4]=authority;vals[5]=t->protocol_pattern;vals[6]=commitment;vals[7]=t->resource_pattern;vals[8]=t->effect_kind;vals[9]=compensation;vals[10]="PROPOSED";vals[11]=at;if(!bind(o->db,"INSERT INTO inverse_cross_owner_residuals(target_id,predicate_id,transformation_id,capability_binding,authority_requirement,protocol_contract,commitment_pattern,resource_pattern,effect_kind,compensation_pattern,state,checked_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(target_id,predicate_id,transformation_id) DO UPDATE SET state=excluded.state,checked_at=excluded.checked_at",12,vals))return 0;snprintf(mission,sizeof(mission),"closure-%08x",inverse_name_hash(target));snprintf(node,sizeof(node),"%s-%08x",t->id,inverse_name_hash(p->predicate_id));r=bf_workgraph_create_mission(o->work,mission);if(r.status!=BF_WORKGRAPH_OK&&r.status!=BF_WORKGRAPH_CONFLICT)return 0;bf_workgraph_register_family(o->work,"closure");spec.mission_id=mission;spec.node_id=node;spec.operator_id=t->protocol_pattern;spec.input_uri=target;spec.family="closure";spec.compensation_operator=!strcmp(t->reversibility,"reversible")?"":compensation;spec.priority=10;spec.timeout_seconds=300;spec.backoff_multiplier=1.0;r=bf_workgraph_add_node(o->work,&spec);return r.status==BF_WORKGRAPH_OK||r.status==BF_WORKGRAPH_CONFLICT;}
static int admit_effect(const char *path,const char *target_id,const char *predicate_id,const char *transformation_id,const char *actor,const char *at){Owners o;BfTargetObligationRecord target;BfTargetPredicateRecord *ps=NULL;size_t n=0,i;const BfTargetPredicateRecord *selected=NULL;const BfInverseTransformationDescriptor*t;char stamp[32];const char *state="REFUSED",*reason="target_not_open",*v[6];if(!open_owners(path,&o))return 1;if(!at||!*at){now_iso(stamp);at=stamp;}t=transformation_named(transformation_id);if(!t||bf_target_obligation_get(o.targets,target_id,&target)!=0||bf_target_obligation_list_predicates(o.targets,target_id,&ps,&n)!=0)goto done;for(i=0;i<n;i++)if(!strcmp(ps[i].predicate_id,predicate_id))selected=&ps[i];if(!selected){reason="predicate_not_owned_by_target";goto done;}if(target.state!=BF_TARGET_OPEN&&target.state!=BF_TARGET_WAITING_EXTERNAL_PREDICATE){reason="target_terminal";goto done;}if(!selected->authority_requirement[0]){reason="effect_authority_requirement_missing";goto done;}if(!actor||bf_authority_has(o.authority,actor,selected->authority_requirement,selected->subject,at,NULL)!=1){reason="effect_authority_missing_or_expired";goto done;}for(i=0;i<t->requires_count;i++){int index=requirement_index(&t->requires[i],ps,n);Evaluation e;if(index<0){reason="transformation_prerequisite_not_declared";goto done;}e=grammar_matches(&ps[index])?evaluate(&o,&ps[index],actor,at):(Evaluation){0,0,"prerequisite_not_in_owner_grammar"};if(!e.satisfied){reason=e.reason;goto done;}}state="ADMISSIBLE_APERTURE";reason="authority_and_declared_prerequisites_rechecked_no_adapter_invoked";done:v[0]=target_id;v[1]=predicate_id;v[2]=transformation_id;v[3]=state;v[4]=reason;v[5]=at?at:"";if(!bind(o.db,"INSERT INTO inverse_effect_admissions(target_id,predicate_id,transformation_id,state,reason,checked_at) VALUES(?,?,?,?,?,?) ON CONFLICT(target_id,predicate_id,transformation_id) DO UPDATE SET state=excluded.state,reason=excluded.reason,checked_at=excluded.checked_at",6,v)){if(ps)bf_target_obligation_free_predicates(ps);close_owners(&o);return 1;}printf("{\"target\":\"%s\",\"predicate\":\"%s\",\"transformation\":\"%s\",\"state\":\"%s\",\"reason\":\"%s\"}\n",target_id,predicate_id,transformation_id,state,reason);if(ps)bf_target_obligation_free_predicates(ps);close_owners(&o);return 0;}
static int synthesize(const char*path,const char*id,const char*actor,const char*at,const char*requested){Owners o;BfTargetObligationRecord target;BfTargetPredicateRecord*ps=NULL;Evaluation*es=NULL;size_t n=0,i,residuals=0;char stamp[32];const BfInversePreferencePolicy*policy;if(!open_owners(path,&o))return 1;if(bf_target_obligation_get(o.targets,id,&target)!=0||bf_target_obligation_list_predicates(o.targets,id,&ps,&n)!=0){close_owners(&o);return 1;}if(target.state!=BF_TARGET_OPEN&&target.state!=BF_TARGET_WAITING_EXTERNAL_PREDICATE){bf_target_obligation_free_predicates(ps);close_owners(&o);return 1;}if(!at||!*at){now_iso(stamp);at=stamp;}policy=policy_named(requested&&*requested?requested:target.preference_policy);if(!policy){bf_target_obligation_free_predicates(ps);close_owners(&o);return 1;}es=calloc(n,sizeof(*es));if(!es){bf_target_obligation_free_predicates(ps);close_owners(&o);return 1;}for(i=0;i<n;i++){const char*vals[6];es[i]=grammar_matches(&ps[i])?evaluate(&o,&ps[i],actor,at):(Evaluation){0,0,"predicate_not_in_generated_owner_grammar"};vals[0]=id;vals[1]=ps[i].predicate_id;vals[2]=ps[i].owner;vals[3]=es[i].satisfied?"SATISFIED":es[i].supported?"UNSATISFIED":"UNSUPPORTED";vals[4]=es[i].reason;vals[5]=at;if(!bind(o.db,"INSERT INTO inverse_predicate_receipts(target_id,predicate_id,owner,state,reason,checked_at) VALUES(?,?,?,?,?,?) ON CONFLICT(target_id,predicate_id) DO UPDATE SET state=excluded.state,reason=excluded.reason,checked_at=excluded.checked_at",6,vals)){free(es);bf_target_obligation_free_predicates(ps);close_owners(&o);return 1;}if(!es[i].satisfied){Candidate candidates[128];size_t c=0,j;const BfInverseTransformationDescriptor*winner;residuals++;for(j=0;j<bf_inverse_transformation_count&&c<128;j++)if(establishes(&bf_inverse_transformations[j],&ps[i])&&requirements_declared(&bf_inverse_transformations[j],ps,n))candidates[c++]=(Candidate){.t=&bf_inverse_transformations[j],.target_index=i};winner=c?select_frontier(candidates,c,policy):NULL;for(j=0;j<c;j++){const char*v[]={id,ps[i].predicate_id,candidates[j].t->id,"0","candidate",at};char ec[32];snprintf(ec,sizeof(ec),"%u",candidates[j].t->eclass);v[3]=ec;v[4]=winner==candidates[j].t?"SELECTED":"PARETO_OR_POLICY_REJECTED";if(!bind(o.db,"INSERT INTO inverse_closure_residuals(target_id,predicate_id,transformation_id,eclass,pareto_state,checked_at) VALUES(?,?,?,?,?,?) ON CONFLICT(target_id,predicate_id,transformation_id) DO UPDATE SET pareto_state=excluded.pareto_state,checked_at=excluded.checked_at",6,v)){free(es);bf_target_obligation_free_predicates(ps);close_owners(&o);return 1;}}if(winner&&!emit_cross_owner(&o,id,&ps[i],winner,at)){free(es);bf_target_obligation_free_predicates(ps);close_owners(&o);return 1;}}} {const char*state=residuals?"OPEN":"FRONTIER_SATISFIED";char number[32];const char*v[5];snprintf(number,sizeof(number),"%zu",residuals);v[0]=id;v[1]=state;v[2]=at;v[3]=number;v[4]=policy->id;if(!bind(o.db,"INSERT INTO inverse_target_receipts(target_id,state,checked_at,residual_count,selection_policy) VALUES(?,?,?,?,?) ON CONFLICT(target_id) DO UPDATE SET state=excluded.state,checked_at=excluded.checked_at,residual_count=excluded.residual_count,selection_policy=excluded.selection_policy",5,v)){free(es);bf_target_obligation_free_predicates(ps);close_owners(&o);return 1;}printf("{\"target\":\"%s\",\"state\":\"%s\",\"residuals\":%zu,\"selection\":\"%s\"}\n",id,state,residuals,policy->id);}free(es);bf_target_obligation_free_predicates(ps);close_owners(&o);return 0;}
/* Reconciliation is deliberately a separate terminal pass.  Synthesis can
 * make a frontier green; only a declared, still-PROVEN ProofFrontier invariant
 * may cross TargetObligation's terminal boundary. */
static int reconcile(const char *path,const char *id,const char *actor,const char *at){Owners o;BfTargetObligationRecord target;BfTargetPredicateRecord *ps=NULL;size_t n=0,i;char stamp[32];const char *state="OPEN",*detail="predicate_residual";const char *invariant="";int all=1,proof=0,rc;const char *v[5];if(!open_owners(path,&o))return 1;if(!at||!*at){now_iso(stamp);at=stamp;}if(bf_target_obligation_get(o.targets,id,&target)!=0||bf_target_obligation_list_predicates(o.targets,id,&ps,&n)!=0){close_owners(&o);return 1;}if(target.state==BF_TARGET_PROVEN||target.state==BF_TARGET_SUPERSEDED){state="TARGET_TERMINAL";detail="target_owner_already_terminal";all=0;goto receipt;}for(i=0;i<n;i++){Evaluation e=grammar_matches(&ps[i])?evaluate(&o,&ps[i],actor,at):(Evaluation){0,0,"predicate_not_in_generated_owner_grammar"};const char *pv[6]={id,ps[i].predicate_id,ps[i].owner,e.satisfied?"SATISFIED":e.supported?"UNSATISFIED":"UNSUPPORTED",e.reason,at};if(!bind(o.db,"INSERT INTO inverse_predicate_receipts(target_id,predicate_id,owner,state,reason,checked_at) VALUES(?,?,?,?,?,?) ON CONFLICT(target_id,predicate_id) DO UPDATE SET state=excluded.state,reason=excluded.reason,checked_at=excluded.checked_at",6,pv)){bf_target_obligation_free_predicates(ps);close_owners(&o);return 1;}if(!e.satisfied){all=0;continue;}if(ps[i].adapter==BF_INVERSE_ADAPTER_PROOF&&!strcmp(ps[i].subject,target.source_frontier)){proof=1;invariant=ps[i].subject;}}if(!all){state="OPEN";detail="one_or_more_owner_predicates_unsatisfied";goto receipt;}if(!proof){state="FRONTIER_SATISFIED_NO_PROOF_FRONTIER";detail="all_owner_predicates_hold_but_target_does_not_declare_a_proven_source_frontier";goto receipt;}rc=bf_proof_close_target(o.proof,o.targets,id,invariant);if(rc<0){bf_target_obligation_free_predicates(ps);close_owners(&o);return 1;}if(rc==1){state="TARGET_PROVEN";detail="proof_owner_closed_target_from_declared_frontier";}else{state="FRONTIER_SATISFIED_PROOF_RECHECK_REFUSED";detail="proof_frontier_changed_before_terminal_boundary";}receipt:v[0]=id;v[1]=state;v[2]=invariant;v[3]=at;v[4]=detail;if(!bind(o.db,"INSERT INTO inverse_target_reconciliations(target_id,state,proof_invariant,checked_at,detail) VALUES(?,?,?,?,?) ON CONFLICT(target_id) DO UPDATE SET state=excluded.state,proof_invariant=excluded.proof_invariant,checked_at=excluded.checked_at,detail=excluded.detail",5,v)){bf_target_obligation_free_predicates(ps);close_owners(&o);return 1;}printf("{\"target\":\"%s\",\"state\":\"%s\",\"proof_invariant\":\"%s\",\"detail\":\"%s\"}\n",id,state,invariant,detail);bf_target_obligation_free_predicates(ps);close_owners(&o);return 0;}
/* The outbox speaks only in immutable dependency-cut envelopes.  Target
 * consumption is deliberately limited to residual synthesis/reconciliation:
 * it never grants authority, makes a commitment, reserves, pays or invokes an
 * external adapter.  ProofFrontier remains the sole terminal path. */
static int inverse_lower_handoff(const char *db_path,const char *handoff,const char *actor,const char *at){
    FILE *file=NULL; char body[8192],schema[128]={0},identity[256]={0},kind[128]={0},lowerer[256]={0};
    sqlite3 *json_db=NULL;sqlite3_stmt *st=NULL;int terminal=0,ok=0;char *target;
    if(!db_path||!*db_path||!handoff||!*handoff)return 0;
    if(!(file=fopen(handoff,"rb"))||!fgets(body,sizeof(body),file)){if(file)fclose(file);return 0;}fclose(file);
    if(sqlite3_open(":memory:",&json_db)!=SQLITE_OK||sqlite3_prepare_v2(json_db,"SELECT COALESCE(json_extract(?1,'$.schema'),''),COALESCE(json_extract(?1,'$.identity'),''),COALESCE(json_extract(?1,'$.candidate_kind'),''),COALESCE(json_extract(?1,'$.lowerer_ref'),'')",-1,&st,NULL)!=SQLITE_OK)goto out;
    sqlite3_bind_text(st,1,body,-1,SQLITE_TRANSIENT);if(sqlite3_step(st)!=SQLITE_ROW)goto out;
    snprintf(schema,sizeof(schema),"%s",sqlite3_column_text(st,0)?(const char*)sqlite3_column_text(st,0):"");
    snprintf(identity,sizeof(identity),"%s",sqlite3_column_text(st,1)?(const char*)sqlite3_column_text(st,1):"");
    snprintf(kind,sizeof(kind),"%s",sqlite3_column_text(st,2)?(const char*)sqlite3_column_text(st,2):"");
    snprintf(lowerer,sizeof(lowerer),"%s",sqlite3_column_text(st,3)?(const char*)sqlite3_column_text(st,3):"");
    if(strcmp(schema,"bonfyre-lowering-handoff.v1")||strcmp(kind,"target_obligation")||strcmp(lowerer,"InverseCompiler:closure_program")||strncmp(identity,"target:",7)||!identity[7])goto out;
    target=identity+7;
    {Owners owners;BfTargetObligationRecord record;if(!open_owners(db_path,&owners))goto out;terminal=bf_target_obligation_get(owners.targets,target,&record)==0&&(record.state==BF_TARGET_PROVEN||record.state==BF_TARGET_SUPERSEDED);close_owners(&owners);}
    if(!terminal&&(synthesize(db_path,target,actor,at,NULL)!=0||reconcile(db_path,target,actor,at)!=0))goto out;
    printf("{\"handoff\":\"");for(const char *p=handoff;*p;p++)putchar(*p=='\"'?'_':*p);printf("\",\"target\":\"%s\",\"state\":\"%s\",\"forbidden_inference\":\"a target cut proposes residuals only; it does not authorize or execute an effect\"}\n",target,terminal?"TARGET_TERMINAL":"RECOMPILED");
    ok=1;
out: if(st)sqlite3_finalize(st);if(json_db)sqlite3_close(json_db);return ok;
}
static int inverse_drain_directory(const char *db_path,const char *directory,const char *actor,const char *at,int limit,int *handled_out){
    DIR *dir=NULL;struct dirent *entry;int handled=0;if(handled_out)*handled_out=0;
    if(!directory||!*directory||limit<1||!(dir=opendir(directory)))return 0;
    while(handled<limit&&(entry=readdir(dir))){char path[1280],done[1344];size_t n=strlen(entry->d_name);
        if(n<6||strcmp(entry->d_name+n-5,".json")||snprintf(path,sizeof(path),"%s/%s",directory,entry->d_name)>=(int)sizeof(path)||snprintf(done,sizeof(done),"%s.handled",path)>=(int)sizeof(done))continue;
        if(!inverse_lower_handoff(db_path,path,actor,at)||rename(path,done)!=0){closedir(dir);return 0;}handled++;
    }closedir(dir);if(handled_out)*handled_out=handled;return 1;
}
static int inverse_drain(const char *db_path,const char *root,const char *actor,const char *at,int limit){
    DIR *dir=NULL;struct dirent *entry;int total=0;if(!db_path||!*db_path||!root||!*root||limit<1||!(dir=opendir(root)))return 0;
    while(total<limit&&(entry=readdir(dir))){char child[1280];struct stat st;int handled=0;
        if(strncmp(entry->d_name,"InverseCompiler-",16)||snprintf(child,sizeof(child),"%s/%s",root,entry->d_name)>=(int)sizeof(child)||stat(child,&st)||!S_ISDIR(st.st_mode))continue;
        if(!inverse_drain_directory(db_path,child,actor,at,limit-total,&handled)){closedir(dir);return 0;}total+=handled;
    }closedir(dir);printf("{\"inverse_handoffs_drained\":%d,\"state\":\"residuals_recompiled\",\"forbidden_inference\":\"draining a TargetObligation cut does not authorize or execute an effect\"}\n",total);return 1;
}
int main(int argc,char**argv){const char*db,*target,*actor,*at,*select,*predicate,*transformation;if(argc<2){usage();return 2;}db=option(argc,argv,"--db");target=option(argc,argv,"--target");actor=option(argc,argv,"--actor");at=option(argc,argv,"--at");select=option(argc,argv,"--select");predicate=option(argc,argv,"--predicate");transformation=option(argc,argv,"--transformation");if(!db){usage();return 2;}
enum{SO_ADMIT,SO_INVERSE_DRAIN,SO_INVERSE_LOWER,SO_RECONCILE,SO_SYNTHESIZE};
static const BfCommandEntry so_commands[]={{"admit",SO_ADMIT,0,NULL},{"inverse-drain",SO_INVERSE_DRAIN,0,NULL},{"inverse-lower",SO_INVERSE_LOWER,0,NULL},{"reconcile",SO_RECONCILE,0,NULL},{"synthesize",SO_SYNTHESIZE,0,NULL}};
const BfCommandEntry *command=bf_command_lookup(so_commands,sizeof(so_commands)/sizeof(so_commands[0]),argv[1]);
if(command&&command->id==SO_INVERSE_LOWER)return inverse_lower_handoff(db,option(argc,argv,"--handoff"),actor,at)?0:2;if(command&&command->id==SO_INVERSE_DRAIN){int limit=option(argc,argv,"--limit")?atoi(option(argc,argv,"--limit")):64;return inverse_drain(db,option(argc,argv,"--lowerer-dir"),actor,at,limit)?0:2;}if(!target){usage();return 2;}if(command&&command->id==SO_SYNTHESIZE)return synthesize(db,target,actor,at,select);if(command&&command->id==SO_RECONCILE)return reconcile(db,target,actor,at);if(command&&command->id==SO_ADMIT&&predicate&&transformation)return admit_effect(db,target,predicate,transformation,actor,at);usage();return 2;}
